78	bool CacheItem::isInUse() const
79	{
80	    std::shared_ptr<const CacheItem> sthis = this->shared_from_this();
81	
82	    // Return true if it is being used anywhere apart from cache and sthis
83	    return sthis.use_count() > 2;
84	}
