151	void Cache::add(CacheItem &item)
152	{
153	    Items savedItems;
154	    {
155	        std::unique_lock lk(Impl::mtx);
156	        int              dev = item.key().deviceId();
157	
158	        if (item.GetSizeInBytes() > doGetDeviceLimit(dev))
159	        {
160	            return;
161	        }
162	
163	        if (item.GetSizeInBytes() + doGetDeviceSize(dev) > doGetDeviceLimit(dev))
164	        {
165	            // Evict only items belonging to this device.
166	            for (auto it = pimpl->items.begin(); it != pimpl->items.end();)
167	            {
168	                if (it->first->deviceId() == dev)
169	                {
170	                    savedItems.insert(pimpl->items.extract(it++));
171	                }
172	                else
173	                {
174	                    ++it;
175	                }
176	            }
177	            Impl::current_size_inbytes[dev] = 0;
178	        }
179	
180	        pimpl->items.emplace(&item.key(), item.shared_from_this());
181	        Impl::current_size_inbytes[dev] += item.GetSizeInBytes();
182	    }
183	}
