185	void Cache::removeAllNotInUseMatching(const IKey &key)
186	{
187	    // When we're removing items, we don't want their
188	    // refcount getting to 0 while the mutex is locked, as
189	    // deleting the object might recursively call removeAllNotInUseMatching,
190	    // leading to a dead lock.
191	    //
192	    // Instead, we gather the removed objects in the vector below, which will
193	    // be destroyed after the mutex is unlocked. When this happens, the items'
194	    // refcount will be decremented, and any object destruction will happen
195	    // after the mutex is unlocked. Recursion can happen in this case, but won't
196	    // lead to deadlocks
197	    std::vector<std::shared_ptr<CacheItem>> holdItemsUntilMtxUnlocked;
198	
199	    {
200	        std::unique_lock lk(Impl::mtx);
201	
202	        auto [firstItem, lastItem] = pimpl->items.equal_range(&key);
203	
204	        auto numItems = std::distance(firstItem, lastItem);
205	
206	        auto it = firstItem;
207	        for (decltype(numItems) i = 0; i < numItems; ++i)
208	        {
209	            if (!it->second->isInUse())
210	            {
211	                holdItemsUntilMtxUnlocked.push_back(it->second);
212	                int dev = it->first->deviceId();
213	                Impl::current_size_inbytes[dev] -= it->second->GetSizeInBytes();
214	                pimpl->items.erase(it++);
215	            }
216	            else
217	            {
218	                ++it;
219	            }
220	        }
221	    }
222	}
