357	std::vector<std::shared_ptr<CacheItem>> Cache::doSnapshotItems() const
358	{
359	    // To avoid keeping mutex locked for too long, let's first gather all items
360	    // into a vector, unlock the mutex, and then iterate through them.
361	    std::vector<std::shared_ptr<CacheItem>> v;
362	
363	    {
364	        std::unique_lock lk(Impl::mtx);
365	        v.reserve(pimpl->items.size());
366	
367	        for (auto it = pimpl->items.begin(); it != pimpl->items.end(); ++it)
368	        {
369	            v.push_back(it->second);
370	        }
371	    }
372	
373	    return v;
374	}
