400	void Cache::Export(py::module &m)
401	{
402	    using namespace pybind11::literals;
403	
404	    py::class_<CacheItem, std::shared_ptr<CacheItem>> cacheItem(nullptr, "CacheItem", py::module_local());
405	
406	    py::class_<ExternalCacheItem, CacheItem, std::shared_ptr<ExternalCacheItem>> externalCacheItem(
407	        nullptr, "ExternalCacheItem", py::module_local());
408	    (void)cacheItem;
409	    (void)externalCacheItem;
410	
411	    // Initialize per-device cache limits to half each GPU's total memory.
412	    // Tolerate hosts with no CUDA device or only a stub libcuda available
413	    // (CPU-only build/CI nodes, CUDA_VISIBLE_DEVICES="", manylinux build
414	    // hosts that resolve libcuda.so.1 to a stub). cudaGetDeviceCount may
415	    // return cudaSuccess with deviceCount=0, cudaErrorNoDevice, or
416	    // cudaErrorStubLibrary. In any of those there is nothing to seed;
417	    // skipping leaves `import cvcuda` working. The cache cannot actually
418	    // be used until a real device is present, so deferring is safe.
419	    {
420	        int deviceCount = 0;
421	        if (cudaError_t err = cudaGetDeviceCount(&deviceCount); err == cudaErrorNoDevice || err == cudaErrorStubLibrary)
422	        {
423	            (void)cudaGetLastError(); // clear sticky error
424	            deviceCount = 0;
425	        }
426	        else
427	        {
428	            util::CheckThrow(err);
429	        }
430	        if (deviceCount > 0)
431	        {
432	            int savedDev = 0;
433	            util::CheckThrow(cudaGetDevice(&savedDev));
434	            for (int d = 0; d < deviceCount; ++d)
435	            {
436	                util::CheckThrow(cudaSetDevice(d));
437	                size_t free_mem;
438	                size_t total_mem;
439	                util::CheckThrow(cudaMemGetInfo(&free_mem, &total_mem));
440	                Impl::cache_limit_inbytes[d] = static_cast<int64_t>(total_mem / 2);
441	            }
442	            util::CheckThrow(cudaSetDevice(savedDev));
443	        }
444	    }
445	
446	    // Make sure cache is cleared up when script ends.
447	    util::RegisterCleanup(m, Cache::ClearAll);
448	
449	    m.def(
450	        "clear_cache",
451	        [](ThreadScope scope)
452	        {
453	            // ResourceGuard releases completed holds through auxiliary-stream callbacks.
454	            // Drain them so clearing the cache also releases their resources.
455	            Stream::SynchronizeAndClearGCBag();
456	            switch (scope)
457	            {
458	            case ThreadScope::GLOBAL:
459	                Cache::ClearAll();
460	                break;
461	            case ThreadScope::LOCAL:
462	                Cache::Instance().clear();
463	                break;
464	            }
465	        },
466	        "scope"_a = ThreadScope::GLOBAL, R"pbdoc(
467	        Clears the NVCV Python cache
468	
469	        Args:
470	            scope (nvcv.ThreadScope): Thread scope that must be either ``nvcv.ThreadScope.GLOBAL`` or ``nvcv.ThreadScope.LOCAL``.
471	    )pbdoc");
472	
473	    m.def(
474	        "cache_size",
475	        [](ThreadScope scope)
476	        {
477	            switch (scope)
478	            {
479	            case ThreadScope::GLOBAL:
480	                return Cache::TotalSize();
481	            case ThreadScope::LOCAL:
482	                return Cache::Instance().size();
483	            }
484	
485	            // Should be unreachable, especially from Python
486	            throw std::invalid_argument("Invalid scope");
487	        },
488	        "scope"_a = ThreadScope::GLOBAL, R"pbdoc(
489	        Returns the quantity of items in the NVCV Python cache
490	
491	        Args:
492	            scope (nvcv.ThreadScope): Thread scope that must be either ``nvcv.ThreadScope.GLOBAL`` or ``nvcv.ThreadScope.LOCAL``.
493	    )pbdoc");
494	
495	    m.def(
496	        "get_cache_limit_inbytes", [] { return Cache::Instance().getCacheLimit(); },
497	        "Returns the cache limit [in bytes] for the current CUDA device.");
498	    m.def(
499	        "set_cache_limit_inbytes",
500	        [](int64_t new_cache_limit_inbytes) { Cache::Instance().setCacheLimit(new_cache_limit_inbytes); },
501	        "Sets the cache limit [in bytes] for the current CUDA device.");
502	
503	    m.def(
504	        "current_cache_size_inbytes", [] { return Cache::Instance().getCurrentSizeInBytes(); },
505	        "Returns the current cache size [in bytes] for the current CUDA device.");
506	
507	    py::module_ internal = m.attr(INTERNAL_SUBMODULE_NAME);
508	    internal.def("nbytes_in_cache", [](const CacheItem &item) { return item.GetSizeInBytes(); });
509	
510	    // Just to check if fetchAll compiles, it's harmless
511	    Cache::Instance().fetchAll<Cache>();
512	}
513	
514	} // namespace nvcvpy::priv
